import Link from "next/link";
import { PageShell } from "@/components/nx/PageShell";
import { ToolsAurora } from "@/components/nx/ToolsAurora";

/**
 * Shared chrome for an in-portal free-tool page: a "back to all tools" link,
 * the standard Nexion page header, and a `.card` wrapper around the reused
 * marketing tool component so it sits inside the dashboard Shell consistently
 * with the rest of the redesigned portal. Lives under app/dashboard/tools/ as
 * a private (underscore-prefixed) module so Next never treats it as a route —
 * one edit here reaches all sixteen tool pages that import it.
 *
 * `narrow`: a tool page is a single form/output panel, not a grid — exactly
 * the case PageShell's `narrow` mode exists for (see its own doc comment).
 *
 * ToolsAurora IS mounted here (each sub-page gets its own instance, same as
 * every other animated-canvas backdrop in the account area unmounting/
 * remounting on navigation — there is no persistence cost being given up).
 * `wisp={false}` on PageShell for the same reason as the hub: its own static
 * radial-gradient patch would otherwise sit on top of this animated one as a
 * visible boxy artifact.
 */
export function ToolPage({
  title,
  sub,
  children,
}: {
  title: string;
  sub: string;
  children: React.ReactNode;
}) {
  return (
    <>
      <ToolsAurora />
      <PageShell eyebrow="TOOLS" title={title} sub={sub} narrow wisp={false}>
        <Link
          href="/dashboard/tools"
          className="-mt-1 inline-flex w-fit items-center gap-1.5 text-[12.5px] font-semibold text-tx-faint transition-colors hover:text-tx-dim"
        >
          ← All tools

