1	import { db } from "@/lib/db";
2	import { requireUser } from "@/lib/auth";
3	import { AutoRefresh } from "@/components/AutoRefresh";
4	import { PageShell } from "@/components/nx/PageShell";
5	import { SslAurora } from "@/components/nx/SslAurora";
6	import {
7	  SslCertificates,
8	  type CertRow,
9	  type QueueInfo,
10	  type ServerOption,
11	} from "@/components/customer/SslCertificates";
12	
13	export const dynamic = "force-dynamic";
14	
15	type SslPayload = { certId?: string; domain?: string; renewal?: boolean };
16	
17	export default async function SslPage() {
18	  const user = await requireUser();
19	
20	  const [certificates, servers] = await Promise.all([
21	    db.sslCertificate.findMany({
22	      where: { userId: user.id },
23	      orderBy: { createdAt: "desc" },
24	    }),
25	    db.server.findMany({
26	      where: { userId: user.id },
27	      orderBy: { createdAt: "desc" },
28	    }),
29	  ]);
30	
31	  const serverName = new Map(servers.map((s) => [s.id, s.hostname]));
32	  const myServerIds = new Set(servers.map((s) => s.id));
33	
34	  // ---------------------------------------------------------------------------
35	  // Queue visibility.
36	  //
37	  // The worker claims ONE job at a time platform-wide — `worker/index.ts` picks
38	  // the oldest `status: "QUEUED"` row and awaits it inside a serial `for(;;)` —
39	  // so a certificate request genuinely can sit behind another tenant's long
40	  // MIGRATE. That happened on 2026-07-26: a request read "pending" for 13
41	  // minutes with nothing on screen to distinguish a queue from a crash, so the
42	  // customer had no way to know whether to wait or retry. Resolve the real
43	  // position here (this page already polls) instead of leaving them guessing.
44	  // ---------------------------------------------------------------------------
45	  const inflight = certificates.filter((c) => c.status === "PENDING" || c.status === "ISSUING");
46	  const queueByCert = new Map<string, QueueInfo>();
47	
48	  if (inflight.length > 0) {
49	    const [sslJobs, running] = await Promise.all([
50	      db.job.findMany({
51	        where: { type: "SSL_ISSUE", status: { in: ["QUEUED", "RUNNING"] } },
52	        select: { id: true, status: true, createdAt: true, payload: true },
53	        orderBy: { createdAt: "asc" },
54	      }),
55	      // Whatever is holding the single worker slot right now.
56	      db.job.findFirst({
57	        where: { status: "RUNNING" },
58	        select: { type: true, serverId: true },
59	        orderBy: { createdAt: "asc" },
60	      }),
61	    ]);
62	
63	    for (const cert of inflight) {
64	      const job = sslJobs.find((j) => ((j.payload ?? {}) as SslPayload).certId === cert.id);
65	
66	      // No queued or running job at all: the request cannot make progress. Say so
67	      // rather than spinning — the reconcile sweep will age it out, and the row is
68	      // deletable in the meantime.
69	      if (!job) {
70	        queueByCert.set(cert.id, {
71	          state: "none",
72	          position: 0,
73	          aheadCount: 0,
74	          queuedAtIso: cert.createdAt.toISOString(),
75	          blocking: null,
76	        });
77	        continue;
78	      }
79	
80	      if (job.status === "RUNNING") {
81	        queueByCert.set(cert.id, {
82	          state: "running",
83	          position: 0,
84	          aheadCount: 0,
85	          queuedAtIso: job.createdAt.toISOString(),
86	          blocking: null,
87	        });
88	        continue;
89	      }
90	
91	      // FIFO by createdAt, matching the worker's claim order exactly.
92	      const aheadCount = await db.job.count({
93	        where: { status: "QUEUED", createdAt: { lt: job.createdAt } },
94	      });
95	      queueByCert.set(cert.id, {
96	        state: "queued",
97	        position: aheadCount + 1,
98	        aheadCount,
99	        queuedAtIso: job.createdAt.toISOString(),
100	        blocking: running
101	          ? {
102	              type: running.type,
103	              // Only the job type is exposed, never whose server it is beyond
104	              // "yours or not" — enough to explain the wait, nothing more.
105	              mine: running.serverId ? myServerIds.has(running.serverId) : false,
106	            }
107	          : null,
108	      });
109	    }
110	  }
111	
112	  const rows: CertRow[] = certificates.map((c) => ({
113	    id: c.id,
114	    domain: c.domain,
115	    status: c.status,
116	    issuer: c.issuer,
117	    autoRenew: c.autoRenew,
118	    serverName: c.serverId ? serverName.get(c.serverId) ?? null : null,
119	    issuedAt: c.issuedAt ? c.issuedAt.toISOString() : null,
120	    // The observed notAfter, or null. Nothing here is ever a computed guess.
121	    expiresAt: c.expiresAt ? c.expiresAt.toISOString() : null,
122	    lastError: c.lastError,
123	    queue: queueByCert.get(c.id) ?? null,
124	  }));
125	
126	  // Certificate issuance needs a live, DNS-pointed server, so only offer running ones.
127	  const serverOptions: ServerOption[] = servers
128	    .filter((s) => s.status === "RUNNING")
129	    .map((s) => ({ id: s.id, hostname: s.hostname }));
130	
131	  const transitional = inflight.length > 0;
132	
133	  return (
134	    <>
135	      {transitional && <AutoRefresh />}
136	      <SslAurora />
137	      <PageShell
138	        eyebrow="NETWORK"
139	        title="SSL Certificates"
140	        sub="One-click Let's Encrypt certificates for domains pointed at your servers. Renewed automatically from 21 days before expiry."
141	        wisp={false}
142	        heroImage="/nx/hero-ssl-shield.webp"
143	      >
144	        <SslCertificates certificates={rows} servers={serverOptions} />
145	      </PageShell>
146	    </>
147	  );
148	}
149

1	"use client";
2	
3	import Link from "next/link";
4	import { useState, useTransition } from "react";
5	import { Badge, StatusDot } from "@/components/ui/primitives";
6	import {
7	  requestCertificate,
8	  renewCertificate,
9	  deleteCertificate,
10	  toggleAutoRenew,
11	} from "@/lib/actions-ssl";
12	
13	/**
14	 * SSL certificate manager for /dashboard/ssl.
15	 *
16	 * Replaces SslManager, whose table could not tell the truth about a certificate:
17	 * it rendered `expiresAt` as a bare date with no notion of whether that date had
18	 * passed (an expired cert kept a green pulsing ACTIVE dot while every visitor got
19	 * NET::ERR_CERT_DATE_INVALID), showed a mid-issuance row as the grey STOPPED dot,
20	 * gave a queued request no explanation at all — one sat "pending" for 13 minutes
21	 * behind another tenant's MIGRATE with nothing on screen to say so — and hard-
22	 * disabled Delete on any ISSUING row, stranding rows a worker restart had
23	 * orphaned.
24	 *
25	 * Every status here is derived from an observed value: `expiresAt` is the
26	 * notAfter read off the certificate (by openssl on the box at issuance, then by a
27	 * TLS read-back of :443 in the renewal sweep), and `lastError` on a non-FAILED
28	 * row means "the certificate exists but something about it is wrong" — most often
29	 * that certbot obtained it in standalone mode and nothing installed it.
30	 */
31	
32	/** Where a still-unfinished request sits in the platform's single serial queue. */
33	export type QueueInfo = {
34	  /** running = certbot is executing; queued = waiting its turn; none = no job at all. */
35	  state: "running" | "queued" | "none";
36	  /** 1 = next to run. Only meaningful when state === "queued". */
37	  position: number;
38	  aheadCount: number;
39	  queuedAtIso: string;
40	  /** The job holding the worker right now, if any. */
41	  blocking: { type: string; mine: boolean } | null;
42	};
43	
44	export type CertRow = {
45	  id: string;
46	  domain: string;
47	  status: string;
48	  issuer: string;
49	  autoRenew: boolean;
50	  serverName: string | null;
51	  issuedAt: string | null;
52	  /** The observed notAfter. Never a computed guess — null means "not verified". */
53	  expiresAt: string | null;
54	  lastError: string | null;
55	  queue: QueueInfo | null;
56	};
57	
58	export type ServerOption = { id: string; hostname: string };
59	
60	const DAY_MS = 86_400_000;
61	
62	function fmtDate(iso: string | null): string {
63	  return iso ? new Date(iso).toISOString().slice(0, 10) : "—";
64	}
65	
66	function daysUntil(iso: string | null): number | null {
67	  if (!iso) return null;
68	  return Math.floor((new Date(iso).getTime() - Date.now()) / DAY_MS);
69	}
70	
71	function ago(iso: string): string {
72	  const mins = Math.max(0, Math.round((Date.now() - new Date(iso).getTime()) / 60_000));
73	  if (mins < 1) return "just now";
74	  if (mins === 1) return "1 minute ago";
75	  if (mins < 60) return `${mins} minutes ago`;
76	  const hrs = Math.round(mins / 60);
77	  return hrs === 1 ? "1 hour ago" : `${hrs} hours ago`;
78	}
79	
80	// Job types the SSL request can be stuck behind. The platform worker is a single
81	// serial queue, so anything here can hold up a certificate.
82	const JOB_LABELS: Record<string, string> = {
83	  MIGRATE: "server migration",
84	  PROVISION: "server build",
85	  REINSTALL: "OS reinstall",
86	  RESIZE: "server resize",
87	  DISK_EXPAND: "disk expansion",
88	  BACKUP_CREATE: "backup",
89	  BACKUP_RESTORE: "backup restore",
90	  SNAPSHOT_CREATE: "snapshot",
91	  SNAPSHOT_ROLLBACK: "snapshot rollback",
92	  SSL_ISSUE: "certificate request",
93	  WEBSITE_SSL: "website SSL setup",
94	  GAME_UPDATE: "game server update",
95	  APP_INSTALL: "app install",
96	};
97	
98	function jobLabel(type: string): string {
99	  return JOB_LABELS[type] ?? type.toLowerCase().replace(/_/g, " ");
100	}
101	
102	// ---------------------------------------------------------------------------
103	// Request form
104	// ---------------------------------------------------------------------------
