310	function CertActions({ cert }: { cert: CertRow }) {
311	  const [error, setError] = useState<string | null>(null);
312	  const [pending, start] = useTransition();
313	
314	  const run = (fn: () => Promise<{ error?: string }>, confirmMsg?: string) => {
315	    if (confirmMsg && !window.confirm(confirmMsg)) return;
316	    start(async () => {
317	      setError(null);
318	      const res = await fn();
319	      if (res?.error) setError(res.error);
320	    });
321	  };
322	
323	  // Only a genuinely executing certbot run blocks deletion. A row stranded in
324	  // ISSUING by a dead worker must be clearable, or the customer can never
325	  // request that domain again.
326	  const issuingNow = cert.status === "ISSUING" && cert.queue?.state === "running";
327	  const canRenew = ["ACTIVE", "EXPIRED", "FAILED"].includes(cert.status);
328	
329	  return (
330	    <div className="flex flex-col items-end gap-1.5">
331	      <div className="flex items-center gap-2">
332	        <button
333	          type="button"
334	          role="switch"
335	          aria-checked={cert.autoRenew}
336	          aria-label="Toggle auto-renew"
337	          disabled={pending}
338	          onClick={() => run(() => toggleAutoRenew(cert.id))}
339	          className={`relative inline-flex h-6 w-11 shrink-0 items-center rounded-full transition-colors ${
340	            cert.autoRenew ? "bg-brand-500" : "bg-white/15"
341	          } ${pending ? "opacity-60" : ""}`}
342	        >
343	          <span
344	            className={`inline-block h-5 w-5 transform rounded-full bg-white shadow transition-transform ${
345	              cert.autoRenew ? "translate-x-5" : "translate-x-0.5"
346	            }`}
347	          />
348	        </button>
349	        {canRenew && (
350	          <button
351	            className="btn-ghost px-3 py-1 text-xs"
352	            disabled={pending}
353	            onClick={() =>
354	              run(
355	                () => renewCertificate(cert.id),
356	                `Reissue the certificate for "${cert.domain}" now? Let's Encrypt allows only 5 identical ` +
357	                  `certificates per week, so use this sparingly.`
358	              )
359	            }
360	          >
361	            Renew now
362	          </button>
363	        )}
364	        <button
365	          className="btn-danger px-3 py-1 text-xs"
366	          disabled={pending || issuingNow}
367	          title={issuingNow ? "certbot is running for this domain right now" : undefined}
368	          onClick={() =>
369	            run(
370	              () => deleteCertificate(cert.id),
371	              `Delete the certificate for "${cert.domain}"? This removes it from your account.`
372	            )
373	          }
374	        >
375	          Delete
376	        </button>
377	      </div>
378	      {!cert.autoRenew && (
379	        <span className="text-xs text-tx-faint">
380	          Auto-renew off — this will not be replaced before it expires.
381	        </span>
382	      )}
383	      {error && <span className="max-w-md text-right text-xs text-red-400">{error}</span>}
384	    </div>
385	  );
386	}
