220	function InstanceCard({ inst }: { inst: NxCloudInstanceView }) {
221	  const [pw, setPw] = useState<string | null>(null);
222	  const [msg, setMsg] = useState("");
223	  const [busy, setBusy] = useState(false);
224	
225	  async function reveal() {
226	    setBusy(true);
227	    const res = await revealNxcloudAdminPassword(inst.id);
228	    setBusy(false);
229	    if (res.error) setMsg(res.error);
230	    else setPw(res.password ?? "");
231	  }
232	  async function reset() {
233	    if (!confirm("Reset the Nextcloud admin password for this cloud?")) return;
234	    setBusy(true);
235	    const res = await resetNxcloudAdminPassword(inst.id);
236	    setBusy(false);
237	    setMsg(res.error ?? "Password reset queued — check back in a moment.");
238	    setPw(null);
239	  }
240	  async function terminate() {
241	    if (!confirm("Permanently delete this cloud and ALL its files? This cannot be undone.")) return;
242	    setBusy(true);
243	    const res = await terminateNxcloud(inst.id);
244	    setBusy(false);
245	    if (res.error) setMsg(res.error);
246	    else window.location.reload();
247	  }
248	  async function retry() {
249	    setBusy(true);
250	    setMsg("");
251	    const res = await retryNxcloud(inst.id);
252	    setBusy(false);
253	    if (res.error) setMsg(res.error);
254	    else window.location.reload();
255	  }
256	
257	  const failed = inst.status === "FAILED";
258	
259	  const usedPct =
260	    inst.storageUsedMB != null && inst.storageQuotaMB > 0
261	      ? Math.min(100, Math.round((inst.storageUsedMB / inst.storageQuotaMB) * 100))
262	      : null;
263	
264	  return (
265	    <div className="card card-hover">
266	      <div className="flex items-start justify-between">
267	        <div>
268	          <div className="font-semibold text-white">{inst.subdomain}</div>
269	          <div className="text-xs text-slate-500">{inst.planName}</div>
270	        </div>
271	        <StatusDot status={inst.status} />
272	      </div>
273	
274	      <div className="mt-3 flex flex-wrap gap-2">
275	        {inst.sslActive && <Badge tone="green">HTTPS</Badge>}
276	        {inst.version && <Badge tone="slate">Nextcloud {inst.version}</Badge>}
277	      </div>
278	
279	      {usedPct != null && (
280	        <div className="mt-3">
281	          <div className="mb-1 flex justify-between text-xs text-slate-400">
282	            <span>Storage</span>
283	            <span>
284	              {Math.round((inst.storageUsedMB ?? 0) / 1024)} / {Math.round(inst.storageQuotaMB / 1024)} GB
285	            </span>
286	          </div>
287	          <div className="h-1.5 w-full overflow-hidden rounded-full bg-white/[0.06]">
288	            <div className="h-full bg-gradient-to-r from-accent-blue to-brand-500" style={{ width: `${usedPct}%` }} />
289	          </div>
290	        </div>
291	      )}
292	
293	      {/* A hard provisioning failure is RED with a retry affordance (mirrors the
294	          hosting "Setup failed + retry"). The amber note is kept only for a live
295	          ACTIVE instance flagged COMPLETED_WITH_ISSUES — a warning, not a failure. */}
296	      {failed ? (
297	        <div className="mt-3 rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-xs text-red-300">
298	          Setup failed{inst.error ? `: ${inst.error}` : ""}.{" "}
299	          <button className="font-medium underline disabled:opacity-50" onClick={retry} disabled={busy}>
300	            {busy ? "Retrying…" : "Retry setup"}
301	          </button>
302	        </div>
303	      ) : (
304	        inst.error && <p className="mt-3 text-xs text-amber-300">{inst.error}</p>
305	      )}
306	
307	      {inst.status === "ACTIVE" && (
308	        <div className="mt-4 space-y-2 rounded-xl border border-white/[0.06] bg-navy-950/50 p-3 text-xs">
309	          <div className="flex justify-between">
310	            <span className="text-slate-500">Admin user</span>
311	            <span className="font-mono text-slate-300">{inst.adminUser}</span>
312	          </div>
313	          <div className="flex items-center justify-between">
314	            <span className="text-slate-500">Admin password</span>
315	            {pw != null ? (
316	              <span className="select-all font-mono text-slate-200">{pw}</span>
317	            ) : (
318	              <button onClick={reveal} disabled={busy} className="text-brand-300 hover:underline">
319	                {busy ? "…" : "Reveal"}
320	              </button>
321	            )}
322	          </div>
323	        </div>
324	      )}
325	
326	      {msg && <p className="mt-2 text-xs text-slate-400">{msg}</p>}
327	
328	      <div className="mt-4 flex flex-wrap gap-2">
329	        <a
330	          href={inst.url}
331	          target="_blank"
332	          rel="noopener noreferrer"
333	          className={`btn-primary text-center text-sm ${inst.status === "ACTIVE" ? "" : "pointer-events-none opacity-50"}`}
334	        >
335	          Open your cloud
336	        </a>
337	        {inst.status === "ACTIVE" && (
338	          <button onClick={reset} disabled={busy} className="btn-secondary text-sm">
339	            Reset admin password
340	          </button>
341	        )}
342	        <button onClick={terminate} disabled={busy} className="btn-secondary text-sm !border-red-500/30 !text-red-300">
343	          Delete
344	        </button>
345	      </div>
346	    </div>
347	  );
348	}
