// Follow-up audit script: migrate preview stages 2-4, outcome states, and
// destination picker with results. Delete when done per repo convention.
import { chromium } from "playwright";
import { mkdirSync } from "node:fs";
import { join } from "node:path";

const BASE = process.env.BASE_URL || "https://v2.q4w8zt3ky6vn2sm.nxeon.cloud";
const EMAIL = process.env.NX_EMAIL || "customer@nxeon.local";
const PASS = process.env.NX_PASS || "wGPZqhCbsLdz";
const out = process.argv[2] || "/tmp/audit-a2b";
mkdirSync(out, { recursive: true });

const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1600, height: 1100 }, deviceScaleFactor: 1 });
const page = await ctx.newPage();

await page.goto(`${BASE}/login`, { waitUntil: "domcontentloaded" });
try { await page.click('text=Got it', { timeout: 4000 }); } catch {}
await page.fill('input[type="email"], input[name="email"]', EMAIL);
await page.fill('input[type="password"], input[name="password"]', PASS);
await Promise.all([
  page.waitForURL((u) => !u.pathname.includes("/login"), { timeout: 45000 }).catch(() => {}),
  page.click("button.btn-primary"),
]);
await page.waitForTimeout(1200);

async function setTheme(mode) {
  await page.evaluate((m) => {
    try {
      localStorage.setItem("nx-theme", m);
      document.documentElement.setAttribute("data-theme", m);
    } catch {}
  }, mode);
}

async function shot(name, opts = {}) {
  for (const mode of ["dark", "light"]) {
    await setTheme(mode);
    await page.waitForTimeout(opts.wait || 900);
    const file = join(out, `${name}-${mode}.png`);
    await page.screenshot({ path: file, fullPage: true });
    console.log(`${name} [${mode}] -> ${file}`);
  }
}

await page.goto(`${BASE}/dashboard/migrate/preview`, { waitUntil: "networkidle", timeout: 60000 });
await page.waitForTimeout(1200);

// Stage 2: Source Details
await page.click("text=2. Source Details");
await shot("stage2-source-details");

// Stage 3: Scan & Detect
await page.click("text=3. Scan & Detect");
await shot("stage3-scan-detect");

// Stage 4: Review
await page.click("text=4. Review");
await shot("stage4-review");

// Stage 5 outcomes
await page.click("text=5. Migrate");
await page.click("text=Completed");
await shot("stage5-completed");

await page.click("text=With issues");
await shot("stage5-withissues");

await page.click("text=Failed");
await shot("stage5-failed");

// Stage 1 destination picker with a search typed in
await page.click("text=1. Select Destination");
await page.waitForTimeout(500);
try {
  await page.fill('input[placeholder*="Search your servers"]', "inline");
  await shot("stage1-search");
} catch (e) {
  console.log("search fill failed:", e.message);
}

await browser.close();

