75	            Page {page} of {pages} · {total} migration{total === 1 ? "" : "s"}
76	          </p>
77	          <span className="ml-auto flex items-center gap-1.5">
78	            <PageLink to={page - 1} disabled={page <= 1} label="Previous" />
79	            {/* A window around the current page rather than every page: a
80	                consolidation can leave dozens, and a hundred numbers is not
81	                navigation. */}
82	            {pageWindow(page, pages).map((n, i) =>
83	              n === null ? (
84	                <span key={`gap-${i}`} className="px-1 text-[12px] text-tx-faint">…</span>
85	              ) : (
86	                <Link
87	                  key={n}
