92	                    (n === page
93	                      ? "border-[#8b5cff]/70 bg-[#7b3fef]/22 text-white"
94	                      : "border-rim-hi bg-well text-tx-dim hover:text-white")
95	                  }
96	                >
97	                  {n}
98	                </Link>
99	              ),
100	            )}
101	            <PageLink to={page + 1} disabled={page >= pages} label="Next" />
102	          </span>
103	        </div>
104	      )}
105	    </div>
106	  );
107	}
108	
109	function PageLink({ to, disabled, label }: { to: number; disabled: boolean; label: string }) {
110	  const cls =
111	    "rounded-[9px] border border-rim-hi px-3 py-1.5 text-[12.5px] font-semibold transition " +
112	    (disabled ? "pointer-events-none opacity-35 text-tx-faint" : "bg-well text-tx-dim hover:text-white");
113	  if (disabled) return <span className={cls}>{label}</span>;
114	  return (
115	    <Link href={to === 1 ? "/dashboard/migrate" : `/dashboard/migrate?mp=${to}`} scroll={false} className={cls}>
116	      {label}
117	    </Link>
118	  );
119	}
120	
121	/** First, last, and the pages either side of the current one. */
122	function pageWindow(page: number, pages: number): (number | null)[] {
123	  if (pages <= 7) return Array.from({ length: pages }, (_, i) => i + 1);
124	  const out: (number | null)[] = [1];
125	  const from = Math.max(2, page - 1);
126	  const to = Math.min(pages - 1, page + 1);
127	  if (from > 2) out.push(null);
128	  for (let n = from; n <= to; n++) out.push(n);
129	  if (to < pages - 1) out.push(null);
130	  out.push(pages);
131	  return out;
132	}
