"use client";

import { useEffect, useMemo, useState } from "react";
import {
  createMigration,
  getMigration,
  getMigrationDnsInfo,
  pointMigrationDns,
  scanSource,
  targetDiskFree,
  finishMigrationSetup,
  recheckMigrationServing,
  type DnsCandidate,
  type MigrationDnsInfo,
  type MigrationRow,
  type RemediationResult,
  type ScanResult,
  type SizingVerdict,
  type TargetInfo,
} from "@/lib/actions-migrate";
import { MigrationStepper } from "@/components/customer/migrate/MigrationStepper";
