import { StatusDot } from "@/components/ui/primitives";
import { CloudflareConnect, CloudflareResultBanner, CloudflareMark, cloudflareStartHref } from "./CloudflareConnect";

/* The destination rows the picker draws. Widened from `{ id, name }`: the
   concept step 1 shows plan, region, address and live state, and a picker that
   names four servers "web-01" tells you nothing about which to pick. */
type ServerOption = DestinationServer;
type OsTemplateOption = { id: string; name: string; family: string; version: string };
type WebAppType = ScanResult["webRoots"][number]["appType"];
type AppRuntime = ScanResult["appDirs"][number]["runtime"];
type AppDirSignature = ScanResult["appDirs"][number]["signature"];

const STEPS = ["Destination", "Where from", "What we found", "Review"] as const;

// App-type badge styling for detected web roots.
const APP_BADGE: Record<WebAppType, { label: string; cls: string }> = {
  wordpress: { label: "WordPress", cls: "border-sky-500/40 bg-sky-500/10 text-sky-300" },
  laravel: { label: "Laravel", cls: "border-orange-500/40 bg-orange-500/10 text-orange-300" },
  django: { label: "Django", cls: "border-emerald-500/40 bg-emerald-500/10 text-emerald-300" },
  node: { label: "Node.js", cls: "border-lime-500/40 bg-lime-500/10 text-lime-300" },
  php: { label: "PHP", cls: "border-violet-500/40 bg-violet-500/10 text-violet-300" },
  unknown: { label: "Files", cls: "border-white/15 bg-white/[0.05] text-slate-300" },
};

// Runtime badge for candidate app directories (Running apps section).
const RUNTIME_BADGE: Record<AppRuntime, { label: string; cls: string }> = {
  node: { label: "Node.js", cls: "border-lime-500/40 bg-lime-500/10 text-lime-300" },
  next: { label: "Next.js", cls: "border-slate-400/40 bg-slate-400/10 text-slate-200" },
  python: { label: "Python", cls: "border-amber-500/40 bg-amber-500/10 text-amber-300" },
  java: { label: "Java", cls: "border-red-500/40 bg-red-500/10 text-red-300" },
  ruby: { label: "Ruby", cls: "border-rose-500/40 bg-rose-500/10 text-rose-300" },
  "php-fpm": { label: "PHP-FPM", cls: "border-violet-500/40 bg-violet-500/10 text-violet-300" },
  pm2: { label: "PM2", cls: "border-cyan-500/40 bg-cyan-500/10 text-cyan-300" },
  dotnet: { label: ".NET", cls: "border-indigo-500/40 bg-indigo-500/10 text-indigo-300" },
  unknown: { label: "App", cls: "border-white/15 bg-white/[0.05] text-slate-300" },
};

// Human label for the on-disk signature we matched in an app directory.
const SIGNATURE_LABEL: Record<AppDirSignature, string> = {
  wordpress: "WordPress files",
  laravel: "Laravel app",
  django: "Django project",
  node: "Node project (package.json)",
  php: "PHP project (composer.json)",
  compose: "Docker Compose project",
  python: "Python project (requirements.txt)",
  "git-repo": "Git repository",
  unknown: "App files",
};

// Client-side guard: a mount path is copyable only if it's a plain absolute path
// (named Docker volumes and other non-paths are shown but never selected). The
// server re-validates every selected path against the strict allowlist regardless.
function isCopyablePath(p: string): boolean {
  return typeof p === "string" && p.startsWith("/") && !p.includes("..") && p.length > 1;
}

