// Follow-up audit: drive the REAL migration wizard modal (steps 1-4) with
// synthetic sandbox data, screenshot dark+light. Delete when done.
import { chromium } from "playwright";
import { mkdirSync } from "node:fs";
import { join } from "node:path";

const BASE = process.env.BASE_URL || "https://v2.q4w8zt3ky6vn2sm.nxeon.cloud";
const EMAIL = process.env.NX_EMAIL || "customer@nxeon.local";
const PASS = process.env.NX_PASS || "wGPZqhCbsLdz";
const out = process.argv[2] || "/tmp/audit-a2c";
mkdirSync(out, { recursive: true });

const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1600, height: 1200 }, deviceScaleFactor: 1 });
const page = await ctx.newPage();

await page.goto(`${BASE}/login`, { waitUntil: "domcontentloaded" });
try { await page.click('text=Got it', { timeout: 4000 }); } catch {}
await page.fill('input[type="email"], input[name="email"]', EMAIL);
await page.fill('input[type="password"], input[name="password"]', PASS);
await Promise.all([
  page.waitForURL((u) => !u.pathname.includes("/login"), { timeout: 45000 }).catch(() => {}),
  page.click("button.btn-primary"),
]);
await page.waitForTimeout(1200);

async function setTheme(mode) {
  await page.evaluate((m) => {
    try {
      localStorage.setItem("nx-theme", m);
      document.documentElement.setAttribute("data-theme", m);
    } catch {}
  }, mode);
}

async function shot(name, opts = {}) {
  for (const mode of ["dark", "light"]) {
    await setTheme(mode);
    await page.waitForTimeout(opts.wait || 900);
    const file = join(out, `${name}-${mode}.png`);
    await page.screenshot({ path: file, fullPage: true });
    console.log(`${name} [${mode}] -> ${file}`);
  }
}

await page.goto(`${BASE}/dashboard/migrate`, { waitUntil: "networkidle", timeout: 60000 });
await page.waitForTimeout(1500);

// Step 1 already selected by default (first server radio). Click Continue.
try {
  await page.click('button:has-text("Continue")', { timeout: 5000 });
  await page.waitForTimeout(800);
} catch (e) { console.log("step1 continue failed:", e.message); }

await shot("wizard-step2-source-form");

// Fill source details form: host, ssh user, ssh port, and password/key.
try {
  const hostInput = page.locator('input[placeholder*="203.0.113" i], input[placeholder*="example" i], input[placeholder*="host" i]').first();
  await hostInput.fill("old.example.com", { timeout: 5000 });
} catch (e) { console.log("host fill failed:", e.message); }

try {
  const userInput = page.locator('input[placeholder*="root" i]').first();
  await userInput.fill("root", { timeout: 3000 });
} catch (e) { console.log("user fill failed:", e.message); }

try {
  const passInput = page.locator('input[type="password"]').first();
  await passInput.fill("synthetic-sandbox-password", { timeout: 3000 });
} catch (e) { console.log("pass fill failed:", e.message); }

await shot("wizard-step2-filled");

try {
  await page.click('button:has-text("Continue")', { timeout: 5000 });
  await page.waitForTimeout(1200);
} catch (e) { console.log("step2 continue failed:", e.message); }

await shot("wizard-step2-after-continue", { wait: 2000 });

// Wait for scan to complete (sandbox synthetic scan) - poll a bit.
await page.waitForTimeout(4000);
await shot("wizard-step3-scan-result", { wait: 1500 });

try {
  await page.click('button:has-text("Continue")', { timeout: 5000 });
  await page.waitForTimeout(1200);
} catch (e) { console.log("step3 continue failed:", e.message); }

await shot("wizard-step4-review", { wait: 1500 });

await browser.close();

