3	import { useEffect, useMemo, useState } from "react";
4	import Link from "next/link";
5	import { Icon } from "@/components/nx/Icon";
6	import { MigrationStepper, MIGRATE_STEPS } from "./MigrationStepper";
7	import { MigrationRunning } from "./MigrationRunning";
8	
9	/**
10	 * A driver for the migration flow's five stages, so the screens can be looked
11	 * at without running a migration.
12	 *
13	 * This exists because step 5 is otherwise unreachable outside a real move: the
14	 * live view is fed by the worker polling loop, and the sandbox runs no worker
15	 * at all, so a sandbox migration sits at "Queued" forever. Steps 1-4 ARE
16	 * walkable here — `scanSource` returns a synthetic detection under
17	 * NXEON_SANDBOX — and this page links straight into them rather than drawing
18	 * copies that would drift from the real screens.
19	 *
20	 * NOTHING HERE IS REAL. No Migration row is read or written, no server action
21	 * is called, no host is contacted. The percentages, stage names and log lines
22	 * are a scripted timeline written to match what worker/migrate-real.ts actually
23	 * reports, purely so the layout can be judged at each stage. The route that
24	 * renders this is gated to the sandbox and to admins.
25	 */
26	
27	type Phase = { pct: number; step: string; lines: string[] };
28	
29	/** Scripted to mirror the engine's real ordered stages and step strings. */
30	const TIMELINE: Phase[] = [
31	  { pct: 5,  step: "Starting…",              lines: ["Queued for a worker", "Preparing migration environment"] },
32	  { pct: 11, step: "Inspecting the old server…", lines: ["Connected to source server (203.0.113.10)", "Reading disk layout and installed services"] },
33	  { pct: 16, step: "Installing prerequisites…",  lines: ["Installing rsync, mysql-client, postgresql-client", "Prerequisites ready"] },
34	  { pct: 21, step: "Preparing storage…",         lines: ["Checking free space on the destination", "3.6 GB needed, 92 GB free"] },
35	  { pct: 25, step: "Recreating accounts…",       lines: ["Recreating 2 system accounts", "Restoring group memberships"] },
36	  { pct: 40, step: "Copying files…",             lines: ["Transferring /var/www (1/3)", "Transferring /home/deploy (2/3)", "File transfer progressing… (58%)"] },
37	  { pct: 55, step: "Copying container data…",    lines: ["Migrating Docker container: nginx (1/6)", "Pulling container image…"] },
38	  { pct: 68, step: "Migrating databases…",       lines: ["Dumping MySQL database: app", "Importing on the destination", "Database migrated successfully"] },
39	  { pct: 82, step: "Securing your site…",        lines: ["Requesting certificates for 2 domains", "Certificate issued"] },
40	  { pct: 98, step: "Finalising…",                lines: ["Running verification checks", "Probing each migrated domain"] },
41	];
42	
43	const OUTCOMES = [
44	  { key: "RUNNING", label: "Running" },
45	  { key: "DONE", label: "Completed" },
46	  { key: "COMPLETED_WITH_ISSUES", label: "With issues" },
47	  { key: "FAILED", label: "Failed" },
48	] as const;
49	
50	type Outcome = (typeof OUTCOMES)[number]["key"];
51	
52	function stamp(offsetSec: number): string {
53	  const d = new Date(Date.now() - (600 - offsetSec) * 1000);
54	  return `[${d.toTimeString().slice(0, 8)}]`;
55	}
56	
57	export function MigrationFlowPreview() {
58	  const [stage, setStage] = useState(4);          // 0-4, the stepper's own index
59	  const [phase, setPhase] = useState(5);          // index into TIMELINE
60	  const [outcome, setOutcome] = useState<Outcome>("RUNNING");
61	  const [playing, setPlaying] = useState(true);
62	
63	  // Walk the scripted phases while playing, so the ring, the checklist and the
64	  // log all move the way they would during a real run.
65	  useEffect(() => {
66	    if (!playing || outcome !== "RUNNING" || stage !== 4) return;
67	    const t = setInterval(() => setPhase((p) => (p + 1) % TIMELINE.length), 2600);
68	    return () => clearInterval(t);
69	  }, [playing, outcome, stage]);
70	
71	  const current = TIMELINE[phase];
72	
73	  const log = useMemo(() => {
74	    const upTo = TIMELINE.slice(0, phase + 1).flatMap((p) => p.lines);
75	    const tail = upTo.slice(-11);
76	    return tail.map((l, i) => `${stamp(i * 47)} ${l}`).join("\n");
77	  }, [phase]);
78	
79	  const terminal = outcome !== "RUNNING";
80	  const progress = terminal ? 100 : current.pct;
81	  const step = outcome === "FAILED" ? "Copying files…" : terminal ? "Completed" : current.step;
82	
83	  return (
84	    <div className="flex flex-col gap-4">
85	      {/* ── what this is ─────────────────────────────────────────────────── */}
86	      <div className="flex flex-wrap items-center gap-3 rounded-[14px] border border-amber-500/35 bg-amber-500/[0.08] px-4 py-3">
87	        <Icon name="warntriangle" size={16} tone="inherit" className="flex-none text-amber-300" />
88	        <p className="min-w-0 flex-1 text-[12.5px] leading-relaxed text-amber-200/90">
89	          <strong className="font-bold text-amber-200">Preview — nothing here is real.</strong>{" "}
90	          No migration is read or started, no host is contacted, and no row exists behind this. It is a
91	          scripted walkthrough of the five stages so the screens can be judged without moving a server.
92	        </p>
93	        <Link
94	          href="/dashboard/migrate"
95	          className="flex-none rounded-[10px] border border-rim-hi bg-well px-3.5 py-2 text-[12.5px] font-semibold text-tx-dim transition hover:text-white"
96	        >
97	          Back to the real page
98	        </Link>
99	      </div>
100	
101	      {/* ── controls ─────────────────────────────────────────────────────── */}
102	      <div className="flex flex-col gap-3 rounded-[16px] border border-rim-hi bg-[rgba(6,14,36,.72)] p-4">
103	        <div className="flex flex-wrap items-center gap-2">
104	          <span className="mr-1 text-[11px] font-bold uppercase tracking-[0.12em] text-tx-faint">Stage</span>
105	          {MIGRATE_STEPS.map((s, i) => (
106	            <button
107	              key={s.label}
108	              type="button"
109	              onClick={() => setStage(i)}
110	              className={
111	                "rounded-[10px] border px-3 py-1.5 text-[12.5px] font-semibold transition " +
112	                (stage === i
113	                  ? "border-[#8b5cff]/70 bg-[#7b3fef]/22 text-white"
114	                  : "border-rim-hi bg-well text-tx-dim hover:text-white")
115	              }
116	            >
117	              {i + 1}. {s.label}
118	            </button>
119	          ))}
120	        </div>
121	
122	        {stage === 4 && (
123	          <div className="flex flex-wrap items-center gap-2">
124	            <span className="mr-1 text-[11px] font-bold uppercase tracking-[0.12em] text-tx-faint">Outcome</span>
125	            {OUTCOMES.map((o) => (
126	              <button
127	                key={o.key}
128	                type="button"
129	                onClick={() => setOutcome(o.key)}
130	                className={
131	                  "rounded-[10px] border px-3 py-1.5 text-[12.5px] font-semibold transition " +
132	                  (outcome === o.key
133	                    ? "border-[#8b5cff]/70 bg-[#7b3fef]/22 text-white"
134	                    : "border-rim-hi bg-well text-tx-dim hover:text-white")
135	                }
136	              >
137	                {o.label}
138	              </button>
139	            ))}
140	
141	            {outcome === "RUNNING" && (
142	              <>
143	                <span className="mx-2 h-5 w-px bg-rim-hi" />
144	                <button
145	                  type="button"
146	                  onClick={() => setPlaying((v) => !v)}
147	                  className="rounded-[10px] border border-rim-hi bg-well px-3 py-1.5 text-[12.5px] font-semibold text-tx-dim transition hover:text-white"
148	                >
149	                  {playing ? "Pause" : "Play"}
150	                </button>
151	                <input
152	                  type="range"
153	                  min={0}
154	                  max={TIMELINE.length - 1}
155	                  value={phase}
156	                  onChange={(e) => { setPlaying(false); setPhase(Number(e.target.value)); }}
157	                  aria-label="Scrub through the migration stages"
158	                  className="h-1.5 w-[190px] cursor-pointer accent-[#7b3fef]"
159	                />
160	                <span className="text-[12px] text-tx-faint">{current.step}</span>
161	              </>
162	            )}
163	          </div>
164	        )}
165	      </div>
166	
167	      {/* ── the stage ────────────────────────────────────────────────────── */}
168	      <div className="rounded-[16px] border border-rim-hi bg-[rgba(4,11,30,.6)] p-4">
169	        <MigrationStepper step={stage} />
170	
171	        {stage === 4 ? (
172	          <MigrationRunning
173	            progress={progress}
174	            step={step}
175	            log={log}
176	            status={outcome}
177	            startedIso={new Date(Date.now() - 23 * 60_000).toISOString()}
178	            plannedPaths={3}
179	            plannedDatabases={1}
180	            plannedBytes={3.6e9}
181	            lastError={outcome === "FAILED" ? "The source server closed the connection while copying /var/www. Nothing was removed from it." : null}
182	          />
183	        ) : (
184	          <div className="rounded-[14px] border border-rim-soft bg-well px-6 py-12 text-center">
185	            <p className="text-[15px] font-bold text-white">{MIGRATE_STEPS[stage].label}</p>
186	            <p className="mx-auto mt-1.5 max-w-[52ch] text-[13px] leading-relaxed text-tx-dim">
187	              {MIGRATE_STEPS[stage].sub}. This stage is the real wizard, not a copy — the scan returns a
188	              synthetic detection in the sandbox, so you can walk steps 1 to 4 with real controls and real
189	              validation.
190	            </p>
191	            <Link href="/dashboard/migrate" className="btn-deploy mt-5 inline-flex py-2.5 text-[13px]">
192	              Open the wizard <span className="dep-arrow">→</span>
193	            </Link>
194	            <p className="mx-auto mt-3 max-w-[52ch] text-[12px] text-tx-faint">
195	              Use <code className="font-mono text-tx-dim">203.0.113.10</code> or{" "}
196	              <code className="font-mono text-tx-dim">old.example.com</code> as the source — the
197	              documentation ranges are accepted here and nowhere else.
198	            </p>
199	          </div>
200	        )}
201	      </div>
202	    </div>
203	  );
204	}
