423	/* The general form of the same fix, for every file this pass did not open.
424	   `text-white`/`bg-white`/`border-white` (bare, 100% opacity) are headings and
425	   want ink — that is what flipping the token above does. Anything with a
426	   slash after "white" is an OPACITY variant — `white/10`, `white/[0.04]`,
427	   `hover:bg-white/20` — and those want a wash relative to whatever the
428	   surface actually is now, not a tint of ink-through-transparency. Matched on
429	   the raw class attribute text, so it does not matter which prefix (hover:,
430	   sm:, etc.) precedes the utility. Gradient stop utilities (from-white/N,
431	   via-white/N, to-white/N) are not covered — those set a custom property
432	   rather than a plain CSS property, so there is no single declaration to
433	   override this way; decorative sheens, not text, so lower cost left as is. */
434	/* Islands are EXCLUDED at the selector, not overridden after the fact —
435	   `revert` does not mean "the value this same rule would have skipped", it
436	   rolls back to a different cascade origin entirely, so it cannot undo an
437	   `!important` sibling rule. `:not()` accepts a full selector list including
438	   descendant combinators, so this reads as "matches, and is not the island and
439	   is not inside one" in one step. Inside dark chrome, "white at 10% opacity on
440	   dark" is already correct in both themes and must stay untouched. */
441	html[data-theme="light"] [class*="bg-white/"]:not(.nx-dark-island, .nx-dark-island *) {
442	  background-color: color-mix(in srgb, var(--fg) 7%, transparent) !important;
443	}
444	html[data-theme="light"] [class*="border-white/"]:not(.nx-dark-island, .nx-dark-island *) {
445	  border-color: color-mix(in srgb, var(--fg) 16%, transparent) !important;
446	}
447	html[data-theme="light"] [class*="text-white/"]:not(.nx-dark-island, .nx-dark-island *) {
448	  color: color-mix(in srgb, var(--fg) 68%, transparent) !important;
449	}
450	
451	/* Calendar's date/time inputs (EventModal, TaskPanel) carry a literal
452	   `[color-scheme:dark]` utility so their native picker icon and dropdown
453	   chrome read correctly against the (then only) dark theme. Left alone, that
454	   forces a dark-styled calendar/clock glyph onto what is now a plain white
455	   `.input` in light mode. Match the surface it is actually sitting on instead
456	   of the hardcoded scheme — `.nx-dark-island` below still wants real dark
457	   chrome and is excluded the same way the rules above are. */
458	html[data-theme="light"] [class*="color-scheme:dark"]:not(.nx-dark-island, .nx-dark-island *) {
459	  color-scheme: light;
460	}
461	
462	html[data-theme="light"] .nx-dark-island {
463	  color-scheme: dark;
464	
465	  --color-void: #00060f;
466	  --color-bg: #000816;
467	  --color-surface: #010f22;
468	  --color-well: #000c1e;
469	  --color-hover: #021428;
470	  --color-side: #00081a;
471	  --color-rim: #002049;
472	  --color-rim-soft: #00173b;
473	  --color-rim-hi: #002a5e;
474	
475	  /* Missed the first time: anything inside the rail or top bar using
476	     bg-navy-900/whatever (the currency switcher, among others) fell through
477	     to the ROOT light-theme navy value — near-white — at whatever opacity the
478	     component asked for, over a dark header. That reads as a grey smear,
479	     which is exactly the reported bug. */
480	  --color-navy-950: #000816;
481	  --color-navy-900: #010f22;
482	  --color-navy-850: #021428;

